import cpmpy as cp
import json

# Input data
n = 8  # Number of words to find
word_length = 8
alphabet = ['A', 'C', 'G', 'T']
complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}

# Model definition
model = cp.Model()

# Decision Variables
words = cp.intvar(0, 3, shape=(n, word_length), name="words")

# Constraints
# Each word has exactly 4 symbols from {C, G}
for i in range(n):
    model += cp.Count([words[i, j] for j in range(word_length)], 1) + cp.Count([words[i, j] for j in range(word_length)], 2) == 4

# Each pair of distinct words differ in at least 4 positions
for i in range(n):
    for j in range(i + 1, n):
        model += cp.sum([words[i, k] != words[j, k] for k in range(word_length)]) >= 4

# Each pair of words (x, y) are such that x^R and y^C differ in at least 4 positions
for i in range(n):
    for j in range(n):
        reverse_complement = [complement[alphabet[words[j, word_length - 1 - k]]] for k in range(word_length)]
        model += cp.sum([alphabet[words[i, k]] != reverse_complement[k] for k in range(word_length)]) >= 4

# Solve and print
if model.solve():
    solution = {'words': [[alphabet[words[i, j].value()] for j in range(word_length)] for i in range(n)]}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

This code models the problem using CPMpy and solves it to find a set of 8 words of length 8 over the alphabet {A, C, G, T} that satisfy the given constraints. The solution is printed in JSON format as specified.

