import cpmpy as cp
import json
import numpy as np

# Input data
n = 5

# Model definition
model = cp.Model()

# Decision Variables
x = cp.intvar(1, n*n, shape=(n, n), name="x")

# Constraints
# All cells must contain unique numbers from 1 to n^2
model += cp.AllDifferent(x)

# Initial position constraint (starting from top-left corner with number 1)
model += x[0, 0] == 1

# Function to add movement constraints
def add_movement_constraints(model, x, n):
    for i in range(n):
        for j in range(n):
            # Get the current cell value
            current = x[i, j]

            # List to store possible next positions
            next_positions = []

            # Check all possible movements
            # Vertical movements
            if i + 3 < n:
                next_positions.append(x[i + 3, j])
            if i - 3 >= 0:
                next_positions.append(x[i - 3, j])
            if j + 3 < n:
                next_positions.append(x[i, j + 3])
            if j - 3 >= 0:
                next_positions.append(x[i, j - 3])

            # Horizontal movements
            if i + 1 < n and j + 2 < n:
                next_positions.append(x[i + 1, j + 2])
            if i + 1 < n and j - 2 >= 0:
                next_positions.append(x[i + 1, j - 2])
            if i - 1 >= 0 and j + 2 < n:
                next_positions.append(x[i - 1, j + 2])
            if i - 1 >= 0 and j - 2 >= 0:
                next_positions.append(x[i - 1, j - 2])
            if i + 2 < n and j + 1 < n:
                next_positions.append(x[i + 2, j + 1])
            if i + 2 < n and j - 1 >= 0:
                next_positions.append(x[i + 2, j - 1])
            if i - 2 >= 0 and j + 1 < n:
                next_positions.append(x[i - 2, j + 1])
            if i - 2 >= 0 and j - 1 >= 0:
                next_positions.append(x[i - 2, j - 1])

            # Diagonal movements
            if i + 2 < n and j + 2 < n:
                next_positions.append(x[i + 2, j + 2])
            if i + 2 < n and j - 2 >= 0:
                next_positions.append(x[i + 2, j - 2])
            if i - 2 >= 0 and j + 2 < n:
                next_positions.append(x[i - 2, j + 2])
            if i - 2 >= 0 and j - 2 >= 0:
                next_positions.append(x[i - 2, j - 2])

            # Ensure that the next position is exactly one more than the current position
            for next_pos in next_positions:
                model += (current + 1 == next_pos).implies(next_pos == current + 1)

# Add movement constraints to the model
add_movement_constraints(model, x, n)

# Solve and print
if model.solve():
    solution = {'x': x.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

This code sets up a CPMpy model to solve the problem of filling an \( n \times n \) grid with numbers from 1 to \( n^2 \) using the specified movement rules. The constraints ensure that each number is placed according to the rules and that all numbers from 1 to \( n^2 \) are used exactly once. The solution is printed in JSON format as specified.

